function gridSurface(mb, rows, ref, colorFn, closedJ = false) {
    const ni = rows.length, nj = rows[0].length, ids = [];
    for (let i = 0; i < ni; i++) {
      const row = [];
      for (let j = 0; j < nj; j++) {
        const p = rows[i][j];
        const pi0 = rows[Math.max(0, i - 1)][j], pi1 = rows[Math.min(ni - 1, i + 1)][j];
        const jm = closedJ ? (j - 1 + nj) % nj : Math.max(0, j - 1), jp = closedJ ? (j + 1) % nj : Math.min(nj - 1, j + 1);
        const pj0 = rows[i][jm], pj1 = rows[i][jp];
        const ux = pi1[0] - pi0[0], uy = pi1[1] - pi0[1], uz = pi1[2] - pi0[2];
        const vx = pj1[0] - pj0[0], vy = pj1[1] - pj0[1], vz = pj1[2] - pj0[2];
        let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
        const r = ref(i, j);
        if (nx * (p[0] - r[0]) + ny * (p[1] - r[1]) + nz * (p[2] - r[2]) < 0) { nx = -nx; ny = -ny; nz = -nz; }
        row.push(mb.v(p[0], p[1], p[2], nx, ny, nz, colorFn ? colorFn(p[0], p[1], p[2], i, j) : null));
      }
      ids.push(row);
    }
    const nq = closedJ ? nj : nj - 1;
    for (let i = 0; i < ni - 1; i++) for (let j = 0; j < nq; j++) mb.quad(ids[i][j], ids[i + 1][j], ids[i + 1][(j + 1) % nj], ids[i][(j + 1) % nj]);
    return ids;
  }

async _buildWorld(map, flow = null, theme = null) {
    const unavailable = UNAVAILABLE_NATIVE_STAGES.find(stage => stage.id === map.id || stage.id === map.layout);
    if (unavailable) throw new RangeError(unavailable.name + '：' + unavailable.reason);
    if (flow && !flow.current()) return;
    const scene = G.scene, ownerFlow = this._matchFlow;
    const world = (this._worldBuild = {});
    const worldCurrent = () => this._worldBuild === world && G.scene === scene &&
      (flow ? flow.current() : this._matchFlow === ownerFlow);
    if (!worldCurrent()) return;
    if (this.preparePropPacks && !await this.preparePropPacks(map.layout || map.id, worldCurrent)) return;
    if (!worldCurrent()) return;
    const layoutId = map.layout || map.id;
    if (this.layoutId === layoutId) {
      if (this._builtQuality !== this.settings?.quality) await applyRuntimeWorldQuality(this, this.settings, this.mobile, { G, effectiveQuality, dressingFor, THREE });
      if (!worldCurrent()) return;
      this.mapDef = map; return;
    }
    if (nativeStageEnabled && NATIVE_IDS.includes(layoutId)) {
      await buildNativeWorld(this, map, worldCurrent); return;
    }
    this._nativeAbort?.abort();
    this._builtQuality = this.settings?.quality;
    // Prepare the replacement detached; retain the current stage during loading.
    const q = effectiveQuality(this.settings, this.mobile);
    // set dressing first: solid props hand back collision boxes that become part of the level (physics, nav, paint)
    const lightmapMetadata = this._prefetchLightmapMetadata?.(layoutId);
    const colliders = [];
    let props = null;
    if (this.PropKit) {
      try {
        props = new this.PropKit(null, { castShadow: true, quality: this.settings.quality });
        if (props.addAll) colliders.push(...await props.addAll(dressingFor(layoutId), { current: worldCurrent }));
        else for (const it of dressingFor(layoutId)) {
          const r = props.add(it.type, it);
          if (r && r.colliders) colliders.push(...r.colliders);
        }
        if (props.buildAsync) await props.buildAsync({ current: worldCurrent }); else props.build();
      } catch (e) { console.error('[inkwave] props failed', e); props?.dispose?.(); props = null; colliders.length = 0; }
    }
    if (!worldCurrent()) { props?.dispose?.(); return; }
    let level, lightmap, physics, nav, pendingLightmap;
    try {
      level = new Level(MAP_LAYOUTS[layoutId], colliders);
      pendingLightmap = this._loadLightmap(level, layoutId, lightmapMetadata).then(value=>({value}),error=>({error}));
      physics = new Physics(level);
      nav = NavGraph.createLegacy ? await NavGraph.createLegacy(level, physics, { current: worldCurrent }) : new NavGraph(level, physics);
      const loadedLightmap=await pendingLightmap;
      if(loadedLightmap.error)throw loadedLightmap.error;
      lightmap=loadedLightmap.value;
    } catch (e) {
      const failedLightmap=pendingLightmap?await pendingLightmap:null;
      failedLightmap?.value?.dispose?.();props?.dispose?.();
      if (!worldCurrent()) return;throw e;
    }
    if (!worldCurrent()) { lightmap?.dispose?.(); props?.dispose?.(); return; }
    const { nextTexlib, oldTexlib } = await syncWorldTexlib(this, layoutId, G.renderer, q.paintAtlas >= 4096 ? 512 : 256, null, STAGE_SURFACES);
    if (!worldCurrent()) { lightmap?.dispose?.(); props?.dispose?.(); if (nextTexlib && nextTexlib !== this.texlib) nextTexlib.dispose(); return; }
    releaseNativeWorld(this);
    if (this.levelMesh) { scene.remove(this.levelMesh, this.grateMesh); this.levelMesh.geometry.dispose(); this.grateMesh?.geometry.dispose(); this.levelMat.dispose(); this.grateMat?.dispose(); }
    const decorTextures = this.decor?.takeStaticTextures?.();
    this.decor?.dispose?.();
    if (this.stageLightmap) { this.stageLightmap.dispose(); this.stageLightmap = null; }
    if (this.props) { this.props.dispose?.(); this.props = null; }
    G.paint?.dispose();
    if (nextTexlib) { this.texlib = nextTexlib; updateLobbyTexlib(this, nextTexlib); } else if (this.texlib?.disposed) { this.texlib = null; updateLobbyTexlib(this, null); }
    if (oldTexlib && oldTexlib !== nextTexlib && !oldTexlib.disposed) oldTexlib.dispose();
    this.layoutId = layoutId;
    this.mapDef = map;
    this.props = props;
    if (props) { props.scene = scene; scene.add(props.group); }
    G.level = level;
    G.physics = physics;
    this.stageLightmap = lightmap;
    this.murals.userData.setStage?.(layoutId);   // the mural atlas's stage decals (ids 4…11) for this layout
    G.paint = new PaintSystem(G.renderer, level, { atlasSize: q.paintAtlas, maxDensity: q.paintAtlas >= 4096 ? 30 : 18 });
    this.levelMat = createLevelMaterial(G.paint.texture, G.paint.size, this.murals, { lightmap, texlib: this.texlib });
    (this.swimWake || (this.swimWake = new SwimWake())).reset();
    this.levelMesh = new THREE.Mesh(level.buildGeometry(G.paint.size), this.levelMat);
    this.levelMesh.castShadow = true; this.levelMesh.receiveShadow = true;
    this.levelMesh.name = 'level';
    scene.add(this.levelMesh);
    // grates: same surface shader, cut-out holes, no ink (they cast no shadow; the mesh is too fine for the shadow map)
    this.grateMesh = this.grateMat = null;
    level.renderTris = 0;
    if (level.faces.some(f => level.blocks[f.block]?.grate)) {
    this.grateMat = createLevelMaterial(G.paint.texture, G.paint.size, this.murals, { grate: true, lightmap, texlib: this.texlib });
    const gg = level.buildGeometry(G.paint.size, (b) => b.grate);
    this.grateMesh = new THREE.Mesh(gg, this.grateMat);
    this.grateMesh.receiveShadow = true; this.grateMesh.visible = gg.index.count > 0;
    scene.add(this.grateMesh);
    }
    this.decor = new Decor(scene, level, decorTextures);
    G.nav = nav;
    const retiredMinimap = this.minimap;
    this.minimap = new Minimap(level, G.paint);
    if (G.env?.rebuildForArena) G.env.rebuildForArena(level.bounds, this._footprint(level), theme);
    else if (G.env?.setFootprint) G.env.setFootprint(this._footprint(level));
    this._shadowRoots();
    if (G.teamColors[0]) this._setPalette(this.palette || this._pickPalette());
    retiredMinimap?.dispose?.();
  }

_prefetchLightmapMetadata(layoutId) {
    if (typeof LIGHTMAP_LAYOUTS !== 'undefined' && LIGHTMAP_LAYOUTS && !LIGHTMAP_LAYOUTS.includes(layoutId)) return Promise.resolve({ absent: true });
    const meta = this._iwLightmapMetadata?.get(layoutId);
    if (meta) return Promise.resolve({ meta });
    try {
      return fetch(`assets/lightmaps/${layoutId}.json`, { cache: 'no-cache' }).then(response => response.json())
        .then(meta => ({ meta }), error => ({ error }));
    } catch (error) { return Promise.resolve({ error }); }
  }

async _loadLightmap(level, layoutId, pendingMetadata = null) {
    try {
      const prepared = pendingMetadata ? await pendingMetadata : null;
      if (prepared?.absent) { for (const f of level.faces) f.light = null; return null; }
      if (prepared?.error) throw prepared.error;
      // Retain only validated small metadata on this Game. Active worlds
      // continue to own and dispose every GPU texture, including on touch.
      const metadata = this._iwLightmapMetadata || (this._iwLightmapMetadata = new Map());
      let meta = metadata.get(layoutId), cached = !!meta;
      // One canonical fetch site also preserves the compiled cache adapter.
      // Only a stale cached entry gets a second validation pass.
      for (let attempt = 0; attempt < 2; attempt++) {
        if (!meta) meta = attempt === 0 && prepared ? prepared.meta : await (await fetch(`assets/lightmaps/${layoutId}.json`, { cache: 'no-cache' })).json();
        level.layoutLightmap(meta.ppm, meta.size);
        if (!cached || level.layoutHash === meta.hash) break;
        metadata.delete(layoutId); meta = null; cached = false;
      }
      if (level.layoutHash !== meta.hash) { console.warn(`[inkwave] lightmap for ${layoutId} is stale — re-run tools/bake-ao.mjs`); level.lightSize = 0; for (const f of level.faces) f.light = null; return null; }
      metadata.delete(layoutId); metadata.set(layoutId, Object.freeze({ hash: meta.hash, ppm: meta.ppm, size: meta.size }));
      while (metadata.size > 4) metadata.delete(metadata.keys().next().value);
      const tex = await new THREE.TextureLoader().loadAsync(`assets/lightmaps/${layoutId}.png?h=${meta.hash}`);
      tex.colorSpace = THREE.NoColorSpace;
      tex.generateMipmaps = true; tex.minFilter = THREE.LinearMipmapLinearFilter; tex.magFilter = THREE.LinearFilter;
      tex.anisotropy = 4;
      return tex;
    } catch (e) {
      console.warn('[inkwave] no lightmap for', layoutId, e.message);
      for (const f of level.faces) f.light = null;
      return null;
    }
  }
